1	import { afterEach, beforeEach, describe, test, expect, vi } from 'vitest';
2	import { resolveBackgroundColour, resolveBorderColour, resolveTextColour, ZimmSizeChip } from './zimmSizeChip.css';
3	
4	/**
5	 * The Figma state cascade (disabled > selected > default) is the part of this recipe that can
6	 * break without surfacing as a type or build error — a mis-ordered branch renders a
7	 * plausible-but-wrong colour. `index.test.tsx` mocks `useMultiStyleConfig` globally, so these
8	 * resolvers are never exercised by any shipped component test; these assertions are the only
9	 * thing that actually calls them. Mirrors zimmTextInput.css.test.ts's pattern for the same class
10	 * of untested-resolver gap.
11	 */
12	
13	// .claude/rules/testing.md asks for beforeEach setup and vi.clearAllMocks() after each test.
14	// The resolvers here are pure and this file mocks nothing, so these hooks are a convention
15	// baseline rather than load-bearing isolation — kept so the file matches the rule as written
16	// and stays correct if a mock is ever introduced.
17	
18	/**
19	 * Matches zimmSizeChip.css.ts's own (module-private, deliberately not re-exported)
20	 * ZimmSizeChipStyleProps shape structurally — TypeScript's structural typing means this file
21	 * doesn't need that type exported to pass a compatible object literal to the resolvers.
22	 */
23	type SizeChipStyleProps = {
24	  selected?: boolean;
25	  disabled?: boolean;
26	};
27	
28	let base: SizeChipStyleProps;
29	
30	beforeEach(() => {
31	  base = { selected: false, disabled: false };
32	});
33	
34	afterEach(() => {
35	  vi.clearAllMocks();
36	});
37	
38	describe('ZimmSizeChip — border colour precedence', () => {
39	  test('default: neither selected nor disabled uses the default field border', () => {
40	    expect(resolveBorderColour(base)).toBe('var(--zimm-color-border-forms)');
41	  });
42	
43	  test('selected (not disabled) uses the focus border colour', () => {
44	    expect(resolveBorderColour({ ...base, selected: true })).toBe('var(--zimm-color-border-focus)');
45	  });
46	
47	  test('disabled (not selected) uses the secondary border colour', () => {
48	    expect(resolveBorderColour({ ...base, disabled: true })).toBe('var(--zimm-color-border-secondary)');
49	  });
50	
51	  test('disabled wins over selected', () => {
52	    expect(resolveBorderColour({ ...base, selected: true, disabled: true })).toBe('var(--zimm-color-border-secondary)');
53	  });
54	});
55	
56	describe('ZimmSizeChip — background colour precedence', () => {
57	  test('default: neither selected nor disabled is transparent', () => {
58	    expect(resolveBackgroundColour(base)).toBe('transparent');
59	  });
60	
61	  test('selected (not disabled) fills with the selected background colour', () => {
62	    expect(resolveBackgroundColour({ ...base, selected: true })).toBe('var(--zimm-color-bg-05)');
63	  });
64	
65	  test('disabled (not selected) stays transparent', () => {
66	    expect(resolveBackgroundColour({ ...base, disabled: true })).toBe('transparent');
67	  });
68	
69	  test('disabled wins over selected — stays transparent, not filled', () => {
70	    expect(resolveBackgroundColour({ ...base, selected: true, disabled: true })).toBe('transparent');
71	  });
72	});
73	
74	describe('ZimmSizeChip — text colour precedence', () => {
75	  test('default: neither selected nor disabled uses the default text colour', () => {
76	    expect(resolveTextColour(base)).toBe('var(--zimm-color-text-default)');
77	  });
78	
79	  test('selected (not disabled) uses the inverse text colour', () => {
80	    expect(resolveTextColour({ ...base, selected: true })).toBe('var(--zimm-color-text-inverse)');
81	  });
82	
83	  test('disabled (not selected) uses the muted text colour', () => {
84	    expect(resolveTextColour({ ...base, disabled: true })).toBe('var(--zimm-color-text-muted)');
85	  });
86	
87	  // This is the exact combination the Scorer proved regresses silently today: inverting the
88	  // disabled/selected precedence order in resolveTextColour let the whole 722-test suite stay
89	  // green. Disabled must win — a disabled chip should never read as selected/inverse-text.
90	  test('disabled wins over selected — muted, not inverse', () => {
91	    expect(resolveTextColour({ ...base, selected: true, disabled: true })).toBe('var(--zimm-color-text-muted)');
92	  });
93	});
94	
95	describe('ZimmSizeChip — recipe wiring', () => {
96	  test('every declared part is produced by baseStyle', () => {
97	    const parts = Object.keys(ZimmSizeChip.baseStyle(base));
98	    expect(parts.sort()).toEqual([...ZimmSizeChip.parts].sort());
99	  });
100	
101	  test('the chip colours reflect the resolved resolvers', () => {
102	    const props = { ...base, selected: true };
103	    const style = ZimmSizeChip.baseStyle(props);
104	    expect(style.chip.borderColor).toBe(resolveBorderColour(props));
105	    expect(style.chip.background).toBe(resolveBackgroundColour(props));
106	    expect(style.chip.color).toBe(resolveTextColour(props));
107	  });
108	});
