5	/**
6	 * The Figma colour cascade is the part of this recipe that can break without surfacing as a
7	 * type or build error — a mis-ordered branch renders a plausible-but-wrong border. These
8	 * assertions moved here from useZimmTextInputState.test.ts when the derivation moved out of
9	 * the hook and into the theme.
10	 */
11	
12	// .claude/rules/testing.md asks for beforeEach setup and vi.clearAllMocks() after each test.
13	// The resolvers here are pure and this file mocks nothing, so these hooks are a convention
14	// baseline rather than load-bearing isolation — kept so the file matches the rule as written
15	// and stays correct if a mock is ever introduced.
16	let base: ZimmTextInputStyleProps;
17	
18	beforeEach(() => {
19	  base = { inverse: false, disabled: false, hasError: false, focused: false, filled: false };
20	});
21	
22	afterEach(() => {
23	  vi.clearAllMocks();
24	});
25	
26	describe('ZimmTextInput — border colour precedence', () => {
27	  test('disabled wins over error and filled', () => {
28	    expect(resolveBorderColour({ ...base, disabled: true, hasError: true, filled: true })).toBe(
29	      'var(--zimm-color-border-forms)',
30	    );
31	  });
32	
33	  test('error wins over focus and filled', () => {
34	    expect(resolveBorderColour({ ...base, hasError: true, filled: true })).toBe('var(--zimm-color-status-error)');
35	  });
36	
37	  test('a filled but unfocused field darkens to the focus colour', () => {
38	    expect(resolveBorderColour({ ...base, filled: true })).toBe('var(--zimm-color-border-focus)');
39	  });
40	
41	  // focused is its own branch, sitting between hasError and filled. In the light palette
42	  // focus and filled resolve to the same colour, so only the empty-and-focused case can
43	  // distinguish "the focus branch ran" from "it fell through to default".
44	  test('an empty but focused field takes the focus colour, not the default', () => {
45	    expect(resolveBorderColour({ ...base, focused: true })).toBe('var(--zimm-color-border-focus)');
46	  });
47	
48	  test('an empty, unfocused, valid field uses the default border', () => {
49	    expect(resolveBorderColour(base)).toBe('var(--zimm-color-border-forms)');
50	  });
51	
52	  test('hover keeps the error colour when in error, otherwise darkens', () => {
53	    expect(resolveHoverBorderColour({ ...base, hasError: true })).toBe('var(--zimm-color-status-error)');
54	    expect(resolveHoverBorderColour(base)).toBe('var(--zimm-color-border-focus)');
55	  });
56	
57	  test('inverse mode uses the inverse palette', () => {
58	    expect(resolveBorderColour({ ...base, inverse: true })).toBe('var(--zimm-color-text-inverse)');
59	    expect(resolveBorderColour({ ...base, inverse: true, hasError: true })).toBe('var(--zimm-color-status-error-bg)');
60	  });
61	});
62	
63	describe('ZimmTextInput — label colour', () => {
64	  test('light mode: subtle once floated, default otherwise', () => {
65	    expect(resolveLabelColour({ ...base, filled: true })).toBe('var(--zimm-color-text-secondary)');
66	    expect(resolveLabelColour(base)).toBe('var(--zimm-color-text-default)');
67	  });
68	
69	  test('inverse mode: grey once floated, white otherwise', () => {
70	    expect(resolveLabelColour({ ...base, inverse: true, filled: true })).toBe('var(--zimm-color-text-inverse-grey)');
71	    expect(resolveLabelColour({ ...base, inverse: true })).toBe('var(--zimm-color-text-inverse)');
72	  });
73	
74	  test('disabled uses the subtle colour for the mode', () => {
75	    expect(resolveLabelColour({ ...base, disabled: true })).toBe('var(--zimm-color-text-secondary)');
76	    expect(resolveLabelColour({ ...base, disabled: true, inverse: true })).toBe('var(--zimm-color-text-inverse-grey)');
77	  });
78	});
79	
80	describe('ZimmTextInput — recipe wiring', () => {
81	  test('every declared part is produced by baseStyle', () => {
82	    const parts = Object.keys(ZimmTextInput.baseStyle(base));
83	    expect(parts.sort()).toEqual([...ZimmTextInput.parts].sort());
84	  });
85	
86	  test('the row border reflects the resolved colour', () => {
87	    expect(ZimmTextInput.baseStyle({ ...base, hasError: true }).row.borderBottom).toContain(
88	      'var(--zimm-color-status-error)',
89	    );
90	  });
91	
92	  test('hover is suppressed when disabled', () => {
93	    // `_hover` is a pseudo-prop, not part of the plain CSS surface of SystemStyleObject.
94	    const row = ZimmTextInput.baseStyle({ ...base, disabled: true }).row as Record<string, unknown>;
95	    expect(row._hover).toBeUndefined();
96	  });
97	
98	  test('the floated label switches size and position', () => {
99	    const resting = ZimmTextInput.baseStyle(base).label;
100	    const floated = ZimmTextInput.baseStyle({ ...base, focused: true }).label;
101	    expect(resting.top).toBe('50%');
102	    expect(floated.top).toBe('var(--zimm-scale-3xs)');
103	    expect(floated.fontSize).toBe('var(--zimm-font-size-4xs)');
104	  });
105	});
