1	import React from 'react';
2	import { describe, test, expect, vi } from 'vitest';
3	import { render, screen, within } from '@testing-library/react';
4	import userEvent from '@testing-library/user-event';
5	import { IntlProvider } from 'react-intl';
6	import { ZimmSizeChipGroup } from './index';
7	import type { ZimmSizeChipValue } from './index';
8	
9	// ZimmSizeChip's own recipe also needs useMultiStyleConfig — mock both layers so tests don't
10	// require a full Chakra theme. The mocked shape only needs to cover this molecule's own two
11	// parts; the atom's `styles.chip` simply resolves to undefined under it, which is a legal,
12	// harmless __css value (see zimmColourSwatchGroup's identical test-file precedent).
13	vi.mock('@chakra-ui/react', async (importOriginal) => {
14	  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
15	  return { ...actual, useMultiStyleConfig: () => ({ radiogroup: {}, oneSize: {} }) };
16	});
17	
18	const wrap = (ui: React.ReactElement) =>
19	  render(
20	    <IntlProvider locale="en" defaultLocale="en">
21	      {ui}
22	    </IntlProvider>,
23	  );
24	
25	const group = () => screen.getByRole('radiogroup', { name: 'Select a size' });
26	const radios = () => screen.getAllByRole('radio');
27	
28	const val = (value: string, label: string, over: Partial<ZimmSizeChipValue> = {}): ZimmSizeChipValue => ({
29	  value,
30	  label,
31	  ...over,
32	});
33	
34	const FOUR = [val('xs', 'XS'), val('s', 'S'), val('m', 'M'), val('l', 'L')];
35	
36	describe('ZimmSizeChipGroup — radiogroup semantics', () => {
37	  test('renders role=radiogroup with an aria-label describing the group', () => {
38	    wrap(<ZimmSizeChipGroup values={FOUR} />);
39	    expect(group()).toBeInTheDocument();
40	  });
41	
42	  test('renders every offered size as a radio', () => {
43	    wrap(<ZimmSizeChipGroup values={FOUR} />);
44	    expect(radios()).toHaveLength(4);
45	  });
46	});
47	
48	describe('ZimmSizeChipGroup — One Size', () => {
49	  test('renders a single non-interactive label, no radiogroup, no radio', () => {
50	    wrap(<ZimmSizeChipGroup values={[val('os', 'One Size')]} />);
51	    expect(screen.getByText('One Size')).toBeInTheDocument();
52	    expect(screen.queryByRole('radiogroup')).not.toBeInTheDocument();
53	    expect(screen.queryAllByRole('radio')).toHaveLength(0);
54	  });
55	
56	  test('clicking around the One Size label calls nothing', async () => {
57	    const onSelect = vi.fn();
58	    const user = userEvent.setup();
59	    wrap(<ZimmSizeChipGroup values={[val('os', 'One Size')]} onSelect={onSelect} />);
60	    await user.click(screen.getByText('One Size'));
61	    expect(onSelect).not.toHaveBeenCalled();
62	  });
63	});
64	
65	describe('ZimmSizeChipGroup — no offered sizes', () => {
66	  test('renders nothing for an empty values array', () => {
67	    const { container } = wrap(<ZimmSizeChipGroup values={[]} />);
68	    expect(container.firstChild).toBeNull();
69	  });
70	});
71	
72	describe('ZimmSizeChipGroup — roving tabindex', () => {
73	  test('exposes exactly one tab stop matching the selected size', () => {
74	    wrap(<ZimmSizeChipGroup values={FOUR} selectedValue="m" />);
75	    const stops = within(group())
76	      .getAllByRole('radio')
77	      .filter((el) => el.getAttribute('tabindex') === '0');
78	    expect(stops).toHaveLength(1);
79	    expect(stops[0]).toHaveTextContent('M');
80	  });
81	
82	  test('falls back to the first size as the tab stop when nothing is selected', () => {
83	    wrap(<ZimmSizeChipGroup values={FOUR} />);
84	    const stops = within(group())
85	      .getAllByRole('radio')
86	      .filter((el) => el.getAttribute('tabindex') === '0');
87	    expect(stops).toHaveLength(1);
88	    expect(stops[0]).toHaveTextContent('XS');
89	  });
90	
91	  test('falls back to the first ENABLED size when the first size is disabled', () => {
92	    const values = [val('xs', 'XS', { isDisabled: true }), val('s', 'S'), val('m', 'M')];
93	    wrap(<ZimmSizeChipGroup values={values} />);
94	    const stops = within(group())
95	      .getAllByRole('radio')
96	      .filter((el) => el.getAttribute('tabindex') === '0');
97	    expect(stops).toHaveLength(1);
98	    // toHaveTextContent does substring matching, so a regression that fell back to the
99	    // disabled 'XS' chip instead of skipping to the enabled 'S' chip would still pass here
100	    // ('XS'.includes('S') === true). Assert DOM identity via the chip's own value attribute
101	    // instead — matches the lowercase value convention ZimmSizeChip sets via data-size-value.
102	    expect(stops[0]).toHaveAttribute('data-size-value', 's');
103	  });
104	
105	  test('a disabled chip is never the roving tab stop, even when two are adjacent', () => {
106	    const values = [val('xs', 'XS', { isDisabled: true }), val('s', 'S', { isDisabled: true }), val('m', 'M')];
107	    wrap(<ZimmSizeChipGroup values={values} />);
108	    const stops = within(group())
109	      .getAllByRole('radio')
110	      .filter((el) => el.getAttribute('tabindex') === '0');
111	    expect(stops).toHaveLength(1);
112	    expect(stops[0]).toHaveTextContent('M');
113	  });
114	
115	  test('tab stop updates and real DOM focus moves after ArrowRight', async () => {
116	    const user = userEvent.setup();
117	    wrap(<ZimmSizeChipGroup values={FOUR} selectedValue="xs" onSelect={vi.fn()} />);
118	    radios()[0].focus();
119	    await user.keyboard('{ArrowRight}');
120	
121	    const stops = within(group())
122	      .getAllByRole('radio')
123	      .filter((el) => el.getAttribute('tabindex') === '0');
124	    expect(stops).toHaveLength(1);
125	    expect(stops[0]).toHaveTextContent('S');
126	    expect(screen.getByRole('radio', { name: 'S' })).toHaveFocus();
127	  });
128	});
129	
130	describe('ZimmSizeChipGroup — arrow key navigation', () => {
131	  test('ArrowRight moves to the next size and calls onSelect', async () => {
132	    const onSelect = vi.fn();
133	    const user = userEvent.setup();
134	    wrap(<ZimmSizeChipGroup values={FOUR} selectedValue="xs" onSelect={onSelect} />);
135	    radios()[0].focus();
136	    await user.keyboard('{ArrowRight}');
