139	
140	  test('ArrowDown behaves the same as ArrowRight', async () => {
141	    const onSelect = vi.fn();
142	    const user = userEvent.setup();
143	    wrap(<ZimmSizeChipGroup values={FOUR} selectedValue="xs" onSelect={onSelect} />);
144	    radios()[0].focus();
145	    await user.keyboard('{ArrowDown}');
146	    expect(onSelect).toHaveBeenCalledWith('s');
147	  });
148	
149	  test('ArrowLeft moves to the previous size and calls onSelect', async () => {
150	    const onSelect = vi.fn();
151	    const user = userEvent.setup();
152	    wrap(<ZimmSizeChipGroup values={FOUR} selectedValue="m" onSelect={onSelect} />);
153	    radios()[2].focus(); // 'm'
154	    await user.keyboard('{ArrowLeft}');
155	    expect(onSelect).toHaveBeenCalledWith('s');
156	  });
157	
158	  test('ArrowUp behaves the same as ArrowLeft', async () => {
159	    const onSelect = vi.fn();
160	    const user = userEvent.setup();
161	    wrap(<ZimmSizeChipGroup values={FOUR} selectedValue="m" onSelect={onSelect} />);
162	    radios()[2].focus();
163	    await user.keyboard('{ArrowUp}');
164	    expect(onSelect).toHaveBeenCalledWith('s');
165	  });
166	
167	  test('ArrowRight wraps from the last size to the first', async () => {
168	    const onSelect = vi.fn();
169	    const user = userEvent.setup();
170	    wrap(<ZimmSizeChipGroup values={FOUR} selectedValue="l" onSelect={onSelect} />);
171	    radios()[3].focus(); // 'l', last
172	    await user.keyboard('{ArrowRight}');
173	    expect(onSelect).toHaveBeenCalledWith('xs');
174	  });
175	
176	  test('ArrowLeft wraps from the first size to the last', async () => {
177	    const onSelect = vi.fn();
178	    const user = userEvent.setup();
179	    wrap(<ZimmSizeChipGroup values={FOUR} selectedValue="xs" onSelect={onSelect} />);
180	    radios()[0].focus();
181	    await user.keyboard('{ArrowLeft}');
182	    expect(onSelect).toHaveBeenCalledWith('l');
183	  });
184	});
185	
186	describe('ZimmSizeChipGroup — disabled sizes are skipped by arrow navigation', () => {
187	  const values = [val('xs', 'XS'), val('s', 'S', { isDisabled: true }), val('m', 'M')];
188	
189	  test('ArrowRight jumps over a disabled size in the middle of the list', async () => {
190	    const onSelect = vi.fn();
191	    const user = userEvent.setup();
192	    wrap(<ZimmSizeChipGroup values={values} selectedValue="xs" onSelect={onSelect} />);
193	    radios()[0].focus();
194	    await user.keyboard('{ArrowRight}');
195	    expect(onSelect).toHaveBeenCalledWith('m');
196	    expect(onSelect).not.toHaveBeenCalledWith('s');
197	  });
198	
199	  test('ArrowLeft jumps over a disabled size in the middle of the list', async () => {
200	    const onSelect = vi.fn();
201	    const user = userEvent.setup();
202	    wrap(<ZimmSizeChipGroup values={values} selectedValue="m" onSelect={onSelect} />);
203	    radios()[2].focus();
204	    await user.keyboard('{ArrowLeft}');
205	    expect(onSelect).toHaveBeenCalledWith('xs');
206	    expect(onSelect).not.toHaveBeenCalledWith('s');
207	  });
208	});
209	
210	describe('ZimmSizeChipGroup — click selection', () => {
211	  test('calls onSelect with the clicked size value', async () => {
212	    const onSelect = vi.fn();
213	    const user = userEvent.setup();
214	    wrap(<ZimmSizeChipGroup values={FOUR} onSelect={onSelect} />);
215	    await user.click(screen.getByRole('radio', { name: 'M' }));
216	    expect(onSelect).toHaveBeenCalledWith('m');
217	  });
218	
219	  test('never calls onSelect when clicking a disabled size', async () => {
220	    const onSelect = vi.fn();
221	    const user = userEvent.setup();
222	    const values = [val('xs', 'XS'), val('s', 'S', { isDisabled: true })];
223	    wrap(<ZimmSizeChipGroup values={values} onSelect={onSelect} />);
224	    await user.click(screen.getByRole('radio', { name: 'S' }));
225	    expect(onSelect).not.toHaveBeenCalled();
226	  });
227	});
