1	import React, { useEffect, useRef, useState } from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { defineMessages, useIntl } from 'react-intl';
4	import { ZimmSizeChip } from '../../atoms/zimmSizeChip';
5	
6	const messages = defineMessages({
7	  groupLabel: { id: 'size_chips.group.label', defaultMessage: 'Select a size' },
8	});
9	
10	const ZIMM_SIZE_CHIP_GROUP_RECIPE = 'ZimmSizeChipGroup';
11	
12	/** One selectable size as the molecule expects it — pre-mapped from the raw SFCC shape. */
13	export type ZimmSizeChipValue = {
14	  value: string;
15	  label: string;
16	  /**
17	   * Mirrors SFCC's orderable/stock flag for this size. Unlike ZimmColourSwatchGroup's colours
18	   * (withheld entirely when unavailable), an unavailable size is shown disabled so the shopper
19	   * can still see the full size run — the size-chip Figma component set includes a dedicated
20	   * Disabled state for exactly this.
21	   */
22	  isDisabled?: boolean;
23	};
24	
25	type ZimmSizeChipGroupProps = {
26	  values: ZimmSizeChipValue[];
27	  /** Currently selected size value (from URL / variation params). */
28	  selectedValue?: string;
29	  /**
30	   * Selection callback. Called on click and on arrow-key navigation landing on a new chip.
31	   * Never called for a disabled size under any input method.
32	   */
33	  onSelect?: (value: string) => void;
34	};
35	
36	/** Index of the first non-disabled entry in `list`, or -1 when every entry is disabled. */
37	const firstEnabledIndex = (list: ZimmSizeChipValue[]): number => list.findIndex((v) => !v.isDisabled);
38	
39	/**
40	 * The roving-tabindex/selection target: the selected value's index when it is itself enabled,
41	 * else the first enabled entry. Kept as a standalone pure function (rather than a closure over
42	 * component props) so the effect below can list its real inputs (`list`, `selected`) directly
43	 * as dependencies, with nothing left out for eslint's exhaustive-deps to flag.
44	 */
45	const computeFocusIndex = (list: ZimmSizeChipValue[], selected: string | undefined): number => {
46	  const selectedIndex = list.findIndex((v) => v.value === selected);
47	  return selectedIndex >= 0 && !list[selectedIndex].isDisabled ? selectedIndex : firstEnabledIndex(list);
48	};
49	
50	/**
51	 * Molecule — the full PDP size-chip group: a `[role=radiogroup]` row of ZimmSizeChip atoms with
52	 * roving tabindex and keyboard navigation, adapted from ZimmColourSwatchGroup's
53	 * handleSwatchesKeyDown for a row with no pagination and a real per-chip disabled state (arrow
54	 * navigation must skip a disabled chip rather than land on or select it).
55	 *
56	 * When exactly one size is offered, the size-chip Figma component set's other Type applies: a
57	 * single non-interactive label renders instead of a one-item radiogroup — a genuinely
58	 * different, non-interactive component, not a radiogroup with one item.
59	 */
60	export const ZimmSizeChipGroup = ({ values, selectedValue, onSelect }: ZimmSizeChipGroupProps) => {
61	  const intl = useIntl();
62	  const groupLabel = intl.formatMessage(messages.groupLabel);
63	  const styles = useMultiStyleConfig(ZIMM_SIZE_CHIP_GROUP_RECIPE, {});
64	
65	  // Roving-tabindex target, tracked as its own state rather than derived fresh every render —
66	  // arrow-key navigation updates it directly so the tab stop (and the imperative focus below)
67	  // moves within a single interaction, without depending on a controlling parent re-passing a
68	  // new `selectedValue` prop first.
69	  const [focusIndex, setFocusIndex] = useState(() => computeFocusIndex(values, selectedValue));
70	
71	  // Re-sync the roving tab stop whenever the selected value or the list itself changes from
72	  // outside this component (e.g. a controlling page changing colour, which can change which
73	  // sizes are disabled).
74	  useEffect(() => {
75	    setFocusIndex(computeFocusIndex(values, selectedValue));
76	  }, [values, selectedValue]);
77	
78	  const radiogroupRef = useRef<HTMLDivElement>(null);
79	  const shouldRefocus = useRef(false);
80	
81	  // Imperative focus after arrow-key navigation — mirrors ZimmColourSwatchGroup's own
82	  // hasNavigated-ref pattern, adapted to fire off this component's own focusIndex state
83	  // directly rather than waiting on a selectedValue round-trip through a controlling parent.
84	  useEffect(() => {
85	    if (!shouldRefocus.current) return;
86	    shouldRefocus.current = false;
87	    const target = values[focusIndex];
88	    if (!target) return;
89	    const el = radiogroupRef.current?.querySelector(`[data-size-value="${target.value}"]`);
90	    (el as HTMLElement | null)?.focus();
91	  }, [focusIndex, values]);
92	
93	  const selectIndex = (index: number, { refocus }: { refocus: boolean }) => {
94	    const target = values[index];
95	    if (!target || target.isDisabled) return;
96	    setFocusIndex(index);
97	    shouldRefocus.current = refocus;
98	    onSelect?.(target.value);
99	  };
100	
101	  const handleChipsKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
102	    if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) return;
103	    e.preventDefault();
104	    if (values.length === 0) return;
105	
106	    // Derive current index from the focused element's data-size-value — a unique value
107	    // identity that survives duplicate display labels, same reasoning as
108	    // zimmColourSwatchGroup's own data-swatch-value lookup.
109	    const focusedValue = (document.activeElement as HTMLElement | null)?.getAttribute('data-size-value');
110	    const focusedIndex = focusedValue ? values.findIndex((v) => v.value === focusedValue) : -1;
111	    const currentIndex = focusedIndex >= 0 ? focusedIndex : focusIndex;
112	    if (currentIndex < 0) return; // every chip disabled — nothing to navigate from
113	
114	    const step = e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : -1;
115	
116	    let nextIndex = currentIndex;
117	    for (let attempt = 0; attempt < values.length; attempt += 1) {
118	      nextIndex = (nextIndex + step + values.length) % values.length;
119	      if (!values[nextIndex].isDisabled) {
120	        selectIndex(nextIndex, { refocus: true });
121	        return;
122	      }
123	    }
124	    // Looped through every chip and found none enabled — nothing to do.
125	  };
126	
127	  // Nothing offered — suppress the group entirely rather than render an empty radiogroup, same
128	  // "nothing to show" precedent as zimmColourSwatchGroup's own offered.length === 0 guard.
129	  if (values.length === 0) return null;
130	
131	  if (values.length === 1) {
132	    return (
133	      <chakra.span __css={styles.oneSize} data-testid="size-chip-one-size">
134	        {values[0].label}
135	      </chakra.span>
136	    );
137	  }
138	
139	  return (
140	    <chakra.div
141	      role="radiogroup"
142	      aria-label={groupLabel}
143	      ref={radiogroupRef}
144	      __css={styles.radiogroup}
145	      onKeyDown={handleChipsKeyDown}
146	    >
147	      {values.map((v, i) => (
148	        <ZimmSizeChip
149	          key={v.value}
150	          value={v.value}
151	          label={v.label}
152	          isSelected={v.value === selectedValue}
153	          isDisabled={v.isDisabled}
154	          isFocusable={i === focusIndex}
155	          onSelect={() => selectIndex(i, { refocus: false })}
156	        />
157	      ))}
158	    </chakra.div>
159	  );
160	};
161	
162	export default ZimmSizeChipGroup;
