1	import type { Meta, StoryObj } from '@storybook/react-webpack5';
2	import { expect, userEvent, within } from 'storybook/test';
3	import React from 'react';
4	import { ZimmSizeChip } from './index';
5	
6	const meta: Meta<typeof ZimmSizeChip> = {
7	  title: 'Commerce/ZimmSizeChip',
8	  component: ZimmSizeChip,
9	  parameters: { layout: 'centered' },
10	  // role="radiogroup" satisfies the ARIA ownership requirement for role="radio" elements
11	  // rendered in isolation — the molecule normally provides this via its chip row.
12	  decorators: [
13	    (Story) => (
14	      <div role="radiogroup" aria-label="Size">
15	        <Story />
16	      </div>
17	    ),
18	  ],
19	};
20	
21	export default meta;
22	type Story = StoryObj<typeof ZimmSizeChip>;
23	
24	/** Unselected, enabled chip. */
25	export const Default: Story = {
26	  args: {
27	    value: 'm',
28	    label: 'M',
29	    isSelected: false,
30	    isFocusable: true,
31	    onSelect: () => {},
32	  },
33	};
34	
35	/** Selected chip — filled treatment, distinct from Default. */
36	export const Selected: Story = {
37	  args: {
38	    value: 'm',
39	    label: 'M',
40	    isSelected: true,
41	    isFocusable: true,
42	    onSelect: () => {},
43	  },
44	};
45	
46	/** Disabled chip — genuinely inert (native `disabled` attribute), muted treatment. */
47	export const Disabled: Story = {
48	  args: {
49	    value: 'm',
50	    label: 'M',
51	    isSelected: false,
52	    isDisabled: true,
53	    isFocusable: false,
54	    onSelect: () => {},
55	  },
56	};
57	
58	/**
59	 * Focus state — demonstrated via a real Tab keypress rather than a static prop, since
60	 * `:focus-visible` cannot be set declaratively. Storybook runs in a real browser (unlike
61	 * Vitest/jsdom), so this exercises the genuine CSS state.
62	 */
63	export const Focus: Story = {
64	  args: {
65	    value: 'm',
66	    label: 'M',
67	    isSelected: false,
68	    isFocusable: true,
69	    onSelect: () => {},
70	  },
71	  play: async ({ canvasElement }) => {
72	    const canvas = within(canvasElement);
73	    const chip = canvas.getByRole('radio', { name: 'M' });
74	    await userEvent.tab();
75	    await expect(chip).toHaveFocus();
76	  },
77	};
